<template>
 <main class="staff-ui organization-page">
  <header class="staff-page-heading"><div><span class="staff-eyebrow">粤宏潮 · 组织管理</span><h1>组织与通讯录</h1><p>维护集团、子集团和部门，员工联系信息与档案保持一致。</p></div><div class="staff-page-actions"><el-button @click="router.push('/staff-management/employees')">员工管理</el-button><el-button v-if="canManage" type="primary" @click="openOrganization()">新增集团</el-button></div></header>
  <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon class="org-error" />
  <div class="organization-layout" v-loading="loading">
   <aside class="staff-panel organization-sidebar"><header><b>集团架构</b><el-button link @click="load" aria-label="刷新组织">刷新</el-button></header><nav aria-label="集团选择"><button v-for="o in organizations" :key="o.id" :class="['organization-node',{selected:selectedId===o.id,child:o.kind!=='group'}]" @click="selectOrganization(o.id)"><span class="organization-mark">{{ o.kind==='group'?'粤':'子' }}</span><span><b>{{ o.name }}</b><small>{{ o.kind==='group'?'集团本部':'子集团' }}</small></span><em>{{ o.employee_count }}</em></button></nav><p>所有子集团归属粤宏潮。员工可直接归属集团本部。</p></aside>
   <section class="staff-panel" v-if="selected">
    <header class="staff-panel-heading"><div><div class="org-title"><h2>{{ selected.name }}</h2><el-tag effect="light" size="small">{{ selected.kind==='group'?'集团本部':'粤宏潮旗下子集团' }}</el-tag></div><p class="staff-muted">{{ selected.employee_count }} 名在职员工 · {{ selected.department_count }} 个部门</p></div><el-button v-if="canManage" @click="openOrganization(selected)">维护集团资料</el-button></header>
    <div class="organization-contacts"><div><small>联系人</small><span>{{ selected.contact_name || '待维护' }}</span></div><div><small>联系电话</small><span>{{ selected.phone || '待维护' }}</span></div><div><small>邮箱</small><span>{{ selected.email || '待维护' }}</span></div><div><small>办公地址</small><span>{{ selected.address || '待维护' }}</span></div></div>
    <div class="staff-panel-body">
     <el-tabs v-model="tab"><el-tab-pane label="员工通讯录" name="directory"/><el-tab-pane label="部门设置" name="departments"/></el-tabs>
     <template v-if="tab==='directory'">
      <div class="directory-tools"><el-input v-model="keyword" clearable placeholder="搜索姓名、手机号、岗位" aria-label="搜索通讯录" @keyup.enter="search"/><el-select v-model="departmentId" clearable placeholder="全部部门" aria-label="筛选部门" @change="search"><el-option v-for="d in currentDepartments" :key="d.id" :label="d.name" :value="d.id"/></el-select><el-button @click="search">查询</el-button></div>
      <el-table :data="entries" v-loading="directoryLoading" empty-text="该集团暂无符合条件的在职员工" class="directory-table"><el-table-column label="员工" min-width="140"><template #default="{row}"><div class="staff-person"><span class="staff-avatar">{{ row.name?.slice(-2) }}</span><b>{{ row.name }}</b></div></template></el-table-column><el-table-column prop="department_name" label="部门" min-width="110"><template #default="{row}">{{ row.department_name || '未分配部门' }}</template></el-table-column><el-table-column prop="position" label="岗位" min-width="130" show-overflow-tooltip/><el-table-column prop="phone" label="手机号" width="135"><template #default="{row}">{{ row.phone || '—' }}</template></el-table-column><el-table-column prop="email" label="邮箱" min-width="170" show-overflow-tooltip><template #default="{row}">{{ row.email || '—' }}</template></el-table-column><el-table-column prop="extension" label="分机" width="80"/><el-table-column v-if="canManage" label="操作" width="90" fixed="right" align="center"><template #default="{row}"><el-button link type="primary" @click="openEntry(row)">维护</el-button></template></el-table-column></el-table>
      <footer class="directory-pagination"><span class="staff-muted">手机号与员工基础档案同步，组织归属在员工管理中调整。</span><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total, prev, pager, next" @current-change="loadDirectory"/></footer>
     </template>
     <template v-else><div class="department-heading"><p class="staff-muted">每个集团独立维护部门及部门联系人。</p><el-button v-if="canManage" type="primary" plain @click="openDepartment()">新增部门</el-button></div><el-table :data="currentDepartments" empty-text="尚未设置部门"><el-table-column prop="name" label="部门名称" min-width="160"/><el-table-column prop="contact_name" label="部门联系人" min-width="120"/><el-table-column prop="phone" label="联系电话" min-width="140"/><el-table-column v-if="canManage" label="操作" width="90"><template #default="{row}"><el-button link type="primary" @click="openDepartment(row)">编辑</el-button></template></el-table-column></el-table></template>
    </div>
   </section>
  </div>
  <el-dialog v-model="organizationVisible" :title="editingOrganization?'维护集团资料':'新增子集团'" width="min(620px,94vw)"><el-form label-position="top"><el-form-item label="集团名称" required><el-input v-model="organizationForm.name" :disabled="!!editingOrganization" maxlength="50" placeholder="填写子集团名称"/></el-form-item><el-form-item label="上级集团"><el-input model-value="粤宏潮" disabled/></el-form-item><div class="org-form-grid"><el-form-item label="联系人"><el-input v-model="organizationForm.contact_name" maxlength="40"/></el-form-item><el-form-item label="联系电话"><el-input v-model="organizationForm.phone" maxlength="30"/></el-form-item></div><el-form-item label="邮箱"><el-input v-model="organizationForm.email" maxlength="120"/></el-form-item><el-form-item label="办公地址"><el-input v-model="organizationForm.address" maxlength="200"/></el-form-item></el-form><template #footer><el-button @click="organizationVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveOrganization">保存集团</el-button></template></el-dialog>
  <el-dialog v-model="departmentVisible" :title="editingDepartment?'编辑部门':'新增部门'" width="min(540px,94vw)"><el-form label-position="top"><el-form-item label="所属集团"><el-input :model-value="selected?.name" disabled/></el-form-item><el-form-item label="部门名称" required><el-input v-model="departmentForm.name" maxlength="50"/></el-form-item><el-form-item label="部门联系人"><el-input v-model="departmentForm.contact_name" maxlength="40"/></el-form-item><el-form-item label="联系电话"><el-input v-model="departmentForm.phone" maxlength="30"/></el-form-item></el-form><template #footer><el-button @click="departmentVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveDepartment">保存部门</el-button></template></el-dialog>
  <el-dialog v-model="entryVisible" :title="`${editingEntry?.name||''} · 通讯录`" width="min(540px,94vw)"><el-form label-position="top"><el-form-item label="所属集团"><el-input :model-value="editingEntry?.store_name" disabled/></el-form-item><el-form-item label="所属部门"><el-select v-model="entryForm.department_id" clearable placeholder="选择部门" style="width:100%"><el-option v-for="d in currentDepartments" :key="d.id" :label="d.name" :value="d.id"/></el-select></el-form-item><el-form-item label="手机号"><el-input v-model="entryForm.phone" maxlength="11"/></el-form-item><el-form-item label="邮箱"><el-input v-model="entryForm.email" maxlength="120"/></el-form-item><div class="org-form-grid"><el-form-item label="分机号"><el-input v-model="entryForm.extension" maxlength="20"/></el-form-item><el-form-item label="办公位置"><el-input v-model="entryForm.office_location" maxlength="100"/></el-form-item></div></el-form><template #footer><el-button @click="entryVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveEntry">保存通讯录</el-button></template></el-dialog>
 </main>
</template>
<script setup>
import {computed,onMounted,reactive,ref} from 'vue'
import {useRouter} from 'vue-router'
import {ElMessage} from 'element-plus'
import {organizationApi as api} from '@/api'
import '@/styles/staff-workspace.css'
const router=useRouter(),organizations=ref([]),departments=ref([]),selectedId=ref(null),canManage=ref(false),loading=ref(false),directoryLoading=ref(false),error=ref(''),saving=ref(false),tab=ref('directory'),entries=ref([]),total=ref(0),page=ref(1),keyword=ref(''),departmentId=ref(null)
const selected=computed(()=>organizations.value.find(o=>o.id===selectedId.value)),currentDepartments=computed(()=>departments.value.filter(d=>d.organization_id===selectedId.value))
let generation=0
async function load(){loading.value=true;error.value='';try{const r=await api.list();organizations.value=r.organizations||[];departments.value=r.departments||[];canManage.value=!!r.can_manage;if(!selected.value)selectedId.value=organizations.value[0]?.id;await loadDirectory()}catch(e){error.value=e.message||'组织信息读取失败'}finally{loading.value=false}}
function selectOrganization(id){selectedId.value=id;page.value=1;keyword.value='';departmentId.value=null;loadDirectory()}
function search(){page.value=1;loadDirectory()}
async function loadDirectory(){if(!selectedId.value)return;const seq=++generation;directoryLoading.value=true;try{const r=await api.directory({organization_id:selectedId.value,department_id:departmentId.value||undefined,keyword:keyword.value||undefined,page:page.value,page_size:20});if(seq!==generation)return;entries.value=r.list||[];total.value=r.total||0}catch(e){if(seq===generation){entries.value=[];ElMessage.error(e.message||'通讯录读取失败')}}finally{if(seq===generation)directoryLoading.value=false}}
const organizationVisible=ref(false),editingOrganization=ref(null),organizationForm=reactive({name:'',contact_name:'',phone:'',email:'',address:''})
function openOrganization(o){editingOrganization.value=o?.id||null;for(const key of Object.keys(organizationForm))organizationForm[key]=o?.[key]||'';organizationVisible.value=true}
async function saveOrganization(){if(!organizationForm.name.trim())return ElMessage.warning('请填写集团名称');saving.value=true;try{const r=editingOrganization.value?await api.update(editingOrganization.value,organizationForm):await api.create(organizationForm);selectedId.value=r.id;organizationVisible.value=false;await load();ElMessage.success('集团资料已保存')}catch(e){ElMessage.error(e.message||'保存失败')}finally{saving.value=false}}
const departmentVisible=ref(false),editingDepartment=ref(null),departmentForm=reactive({name:'',contact_name:'',phone:''})
function openDepartment(d){editingDepartment.value=d?.id||null;for(const key of Object.keys(departmentForm))departmentForm[key]=d?.[key]||'';departmentVisible.value=true}
async function saveDepartment(){if(!departmentForm.name.trim())return ElMessage.warning('请填写部门名称');saving.value=true;try{await api.saveDepartment(editingDepartment.value,{...departmentForm,organization_id:selectedId.value});departmentVisible.value=false;await load();ElMessage.success('部门已保存')}catch(e){ElMessage.error(e.message||'保存失败')}finally{saving.value=false}}
const entryVisible=ref(false),editingEntry=ref(null),entryForm=reactive({department_id:null,phone:'',email:'',extension:'',office_location:''})
function openEntry(e){editingEntry.value=e;for(const key of Object.keys(entryForm))entryForm[key]=e[key]??(key==='department_id'?null:'');entryVisible.value=true}
async function saveEntry(){saving.value=true;try{await api.saveEntry(editingEntry.value.id,entryForm);entryVisible.value=false;await loadDirectory();ElMessage.success('通讯录已保存，手机号已同步员工档案')}catch(e){ElMessage.error(e.message||'保存失败')}finally{saving.value=false}}
onMounted(load)
</script>
<style scoped>
.organization-layout{display:grid;grid-template-columns:230px minmax(0,1fr);gap:20px;align-items:start}.organization-sidebar{padding:8px}.organization-sidebar header{display:flex;justify-content:space-between;align-items:center;padding:10px 12px 14px}.organization-sidebar header b{font-size:13px}.organization-sidebar nav{display:grid;gap:5px}.organization-node{border:0;background:transparent;text-align:left;display:flex;align-items:center;gap:10px;width:100%;padding:12px;border-radius:8px;cursor:pointer;color:var(--staff-text);font:inherit}.organization-node.child{padding-left:24px}.organization-node.selected,.organization-node:hover{background:var(--el-color-primary-light-9,#eef4ff)}.organization-node.selected b{color:var(--staff-blue)}.organization-mark{height:30px;width:30px;flex:none;display:grid;place-items:center;border:1px solid var(--staff-line);border-radius:8px;font-size:12px;color:var(--staff-blue);background:var(--staff-surface)}.organization-node>span:nth-child(2){display:grid;gap:4px}.organization-node b{font-size:13px;font-weight:600}.organization-node small,.organization-node em{font-size:11px;color:var(--staff-muted);font-style:normal}.organization-node em{margin-left:auto}.organization-sidebar>p{font-size:12px;color:var(--staff-muted);padding:12px;line-height:1.8;margin:12px 0 0;border-top:1px solid var(--staff-line)}.org-title{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.organization-contacts{display:grid;grid-template-columns:1fr 1fr 1.4fr 1.5fr;gap:18px;padding:18px 20px;border-bottom:1px solid var(--staff-line)}.organization-contacts>div{display:grid;gap:7px;min-width:0}.organization-contacts small{font-size:11px;color:var(--staff-muted)}.organization-contacts span{font-size:12px;overflow-wrap:anywhere}.directory-tools{display:flex;gap:12px;align-items:center;margin:0 0 18px}.directory-tools>.el-input{max-width:300px}.directory-tools>.el-select{max-width:180px}.directory-pagination{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-top:20px}.department-heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:15px}.org-form-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.org-error{margin-bottom:16px}
@media(max-width:1000px){.organization-layout{grid-template-columns:190px minmax(0,1fr)}.organization-contacts{grid-template-columns:1fr 1fr}.organization-node.child{padding-left:12px}}
@media(max-width:700px){.organization-layout{grid-template-columns:1fr}.organization-sidebar nav{display:flex;overflow-x:auto}.organization-node,.organization-node.child{width:auto;min-width:145px;flex:none;padding:12px}.organization-sidebar>p{display:none}.directory-tools{flex-wrap:wrap}.directory-tools>.el-input{max-width:100%;width:100%}.directory-tools>.el-select{max-width:none;flex:1}.organization-contacts{gap:16px}.org-form-grid{grid-template-columns:1fr;gap:0}}
</style>
